#include "ivfc_bridge.h"
#include "sha256.h"
#include <assert.h>
#include <stdio.h>
#include <string.h>
static unsigned checks;
#define CHECK(e) do{checks++;assert(e);}while(0)
int main(void) {
    static const char *const labels[]={"HierarchicalIntegrityVerificationStorage::Master","HierarchicalIntegrityVerificationStorage::L1","HierarchicalIntegrityVerificationStorage::L2","HierarchicalIntegrityVerificationStorage::L3"};
    FILE *f=fopen("tests/corpus/ivfc-hmac-vectors.bin","rb");CHECK(f!=NULL);
    uint8_t count[4];CHECK(fread(count,1,4,f)==4&&count[0]==64&&count[1]==0&&count[2]==0&&count[3]==0);
    for(unsigned vector=0;vector<64;vector++) {
        uint8_t seed[32],expected[32],fixed[32],old[32];CHECK(fread(seed,1,32,f)==32);
        for(unsigned level=0;level<4;level++) {
            CHECK(fread(expected,1,32,f)==32);size_t n=strlen(labels[level]);
            btd_ivfc_hmac(seed,labels[level],n,fixed);bsr_hmac256(seed,labels[level],n,old);
            CHECK(!memcmp(fixed,expected,32));CHECK(memcmp(old,expected,32)!=0);
        }
    }
    CHECK(fgetc(f)==EOF&&fclose(f)==0);
    printf("IVFC HMAC: %u checks passed (256 independent vectors; legacy direction fails)\n",checks);return 0;
}
